<?php declare(strict_types=1);use FastWebsite\Core\View;$x=static fn(string$f):string=>(string)($values[$f]??'');$dt=static fn(string$v):string=>$v!==''?str_replace(' ','T',substr($v,0,16)):'';$edit=is_int($itemId);?>
<section class="admin-page-heading"><div><p class="eyebrow">Notice</p><h1><?=$edit?'Edit announcement':'Create announcement'?></h1><p>Use an optional date window to show and retire the notice automatically.</p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/pages#announcements">Cancel</a></section><?php if($errors!==[]):?><div class="form-alert"><ul><?php foreach($errors as$e):?><li><?=View::escape($e)?></li><?php endforeach;?></ul></div><?php endif;?><form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/pages/announcements<?=$edit?'/'.$itemId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>"><section class="form-section"><div class="form-grid"><div class="form-field span-2"><label>Title *</label><input name="title" required value="<?=View::escape($x('title'))?>"></div><div class="form-field"><label>Type</label><select name="announcement_type"><?php foreach(['general','opportunity','admissions','scholarship','notice','urgent']as$t):?><option<?=$x('announcement_type')===$t?' selected':''?>><?=$t?></option><?php endforeach;?></select></div><div class="form-field"><label>Link</label><input name="link_url" value="<?=View::escape($x('link_url'))?>"></div><div class="form-field span-2"><label>Summary</label><textarea name="summary" rows="5"><?=View::escape($x('summary'))?></textarea></div><div class="form-field"><label>Show from</label><input type="datetime-local" name="starts_at" value="<?=View::escape($dt($x('starts_at')))?>"></div><div class="form-field"><label>Show until</label><input type="datetime-local" name="ends_at" value="<?=View::escape($dt($x('ends_at')))?>"></div><label><input type="checkbox" name="is_pinned" value="1"<?=$x('is_pinned')==='1'?' checked':''?>> Pin this announcement</label></div></section><div class="form-actions"><button class="button button-secondary" name="submit_action" value="save">Save</button><button class="button button-primary" name="submit_action" value="publish">Save and publish</button></div></form>
